contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address _log) public payable {
        require(_log != address(0));

        bool initializedBefore = false;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { initializedBefore = false; } else { initializedBefore = true; }

        bool reverted;
        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted = true; } else { reverted = false; }

        bool initializedAfter;
        c.Initialized(); bool __rev2 = __ESBMC_reverted(); if (__rev2) { initializedAfter = false; } else { initializedAfter = true; }

        assert((!reverted) == !initializedBefore && initializedAfter == initializedBefore);
    }
}

